// Tabs: a tap picks one, the one under the mouse lights up (hover:).
const tabs = ['Today', 'Week', 'Month']
let active = 0

const steps = [6.2, 8.4, 4.1, 9.8, 7.3, 11.2, 5.6]
const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']

const Today = () => (
  <div className="flex flex-col items-center justify-center h-full gap-2">
    <span className="text-8xl font-bold">7,341</span>
    <span className="text-2xl text-zinc-400">steps so far today</span>
  </div>
)

const Week = () => (
  <div className="flex items-end gap-4 h-full">
    {steps.map((k, i) => (
      <div className="flex-1 flex flex-col items-center gap-2 h-full justify-end">
        <span className="text-sm text-zinc-400">{`${k}k`}</span>
        <div className={`w-full rounded-t-lg ${i === 5 ? 'bg-lime-400' : 'bg-lime-400/40'} h-[${Math.round(k * 7)}%]`} />
        <span className="text-zinc-300">{days[i]}</span>
      </div>
    ))}
  </div>
)

const Month = () => (
  <div className="grid grid-cols-7 gap-2 h-full">
    {Array.from({ length: 28 }).map((_, i) => (
      <div className={`rounded-md ${['bg-lime-400', 'bg-lime-400/60', 'bg-lime-400/30', 'bg-zinc-800'][(i * 7 + 3) % 4]}`} />
    ))}
  </div>
)

export function get(app) {
  return (
    <div className="flex flex-col bg-zinc-900 text-white">
      <div className="flex items-center gap-2 p-4 border-b border-white/10">
        {tabs.map((tab, i) => (
          <div className={`px-6 py-3 rounded-lg text-xl ${i === active ? 'bg-white text-zinc-900 font-semibold' : 'text-zinc-400 hover:bg-white/10 hover:text-white'}`}
            onClick={() => { active = i }}>{tab}</div>
        ))}
        <span className="flex-1 text-right text-zinc-500">Steps</span>
      </div>
      <div className="flex-1 p-6">{[<Today />, <Week />, <Month />][active]}</div>
    </div>
  )
}
